. "$PSScriptRoot\Assert.ps1"
$ErrorActionPreference='Stop'
Set-StrictMode -Version Latest
Import-Module (Join-Path $PSScriptRoot '..\lib\StandardSourceMaterial.psm1') -Force -DisableNameChecking

function Get-LowerHash([string]$Path){return (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant()}
function New-SourceFixture([string]$Root,[int]$LineCount){
    $sourcePath=Join-Path $Root 'src\app.ts';New-Item -ItemType Directory -Path (Split-Path -Parent $sourcePath) -Force|Out-Null
    $lines=@(1..$LineCount|ForEach-Object{'export const line'+$_.ToString('D5')+' = '+$_+';'});[IO.File]::WriteAllText($sourcePath,($lines-join"`n"),[Text.UTF8Encoding]::new($false))
    $entry=[pscustomobject]@{path='src/app.ts';lines=$LineCount;bytes=(Get-Item $sourcePath).Length;sha256=Get-LowerHash $sourcePath}
    $canonical='{0}|{1}|{2}|{3}'-f$entry.path,$entry.lines,$entry.bytes,$entry.sha256;$bytes=[Text.UTF8Encoding]::new($false).GetBytes($canonical);$digest=[BitConverter]::ToString(([Security.Cryptography.SHA256]::Create().ComputeHash($bytes))).Replace('-','').ToLowerInvariant()
    return [pscustomobject]@{manifestVersion='1.0';templateId='project_task_management';totalFiles=1;totalLines=$LineCount;sha256=$digest;files=@($entry)}
}
function Get-DocxVariable([string]$Path,[string]$Name){
    Add-Type -AssemblyName System.IO.Compression;Add-Type -AssemblyName System.IO.Compression.FileSystem;$archive=[IO.Compression.ZipFile]::OpenRead($Path)
    try{$entry=$archive.GetEntry('word/settings.xml');$reader=[IO.StreamReader]::new($entry.Open());try{[xml]$xml=$reader.ReadToEnd()}finally{$reader.Dispose()};$ns='http://schemas.openxmlformats.org/wordprocessingml/2006/main';$manager=[Xml.XmlNamespaceManager]::new($xml.NameTable);$manager.AddNamespace('w',$ns);$node=$xml.SelectSingleNode("//w:docVar[@w:name='$Name']",$manager);if($null-eq$node){return ''};return $node.GetAttribute('val',$ns)}finally{$archive.Dispose()}
}

$root=Join-Path ([IO.Path]::GetTempPath()) ('standard-source-material-'+[guid]::NewGuid().ToString('N'))
try{
    $shortRoot=Join-Path $root 'short';$shortManifest=New-SourceFixture $shortRoot 1000;$short=Get-StandardSourcePrintPlan -RepositoryRoot $shortRoot -SourceManifest $shortManifest
    Assert-Equal $short.linesPerPage 50;Assert-Equal $short.totalSourcePages 20;Assert-Equal $short.expectedPageCount 20;Assert-Equal $short.trimRequired $false
    Assert-Equal (($short.pages|ForEach-Object sourcePage)-join',') ((1..20)-join',');Assert-Equal $short.selectedLineCount 1000
    foreach($page in @($short.pages)){Assert-Equal @($page.lines).Count 50}

    $longRoot=Join-Path $root 'long';$longManifest=New-SourceFixture $longRoot 5000;$long=Get-StandardSourcePrintPlan -RepositoryRoot $longRoot -SourceManifest $longManifest
    Assert-Equal $long.totalSourcePages 100;Assert-Equal $long.expectedPageCount 60;Assert-Equal $long.trimRequired $true
    Assert-Equal $long.firstRange '1-30';Assert-Equal $long.lastRange '71-100'
    Assert-Equal (($long.pages|ForEach-Object sourcePage)-join',') ((@(1..30)+@(71..100))-join',');Assert-Equal $long.selectedLineCount 3000
    foreach($page in @($long.pages)){Assert-Equal @($page.lines).Count 50}
    $longAgain=Get-StandardSourcePrintPlan -RepositoryRoot $longRoot -SourceManifest $longManifest
    Assert-Equal $long.selectionSha256 $longAgain.selectionSha256;Assert-Equal $long.sourceManifestSha256 ([string]$longManifest.sha256)

    $htmlPath=Join-Path $root 'source.html';$html=Write-StandardSourceHtml -Plan $long -SoftwareName '边缘云智能业务分发平台软件' -Version '1.0.0' -OutputPath $htmlPath
