    Assert-Match $html ('data-source-manifest-sha256="'+[regex]::Escape([string]$longManifest.sha256)+'"')
    Assert-Match $html 'data-source-page="1"';Assert-Match $html 'data-source-page="100"';Assert-Equal ($html-match'data-source-page="50"') $false
    Assert-Match $html 'line00001';Assert-Match $html 'line05000';Assert-Equal ($html-match'line02500') $false
