    Assert-Equal ($html-match'F\d{3}(?:\s*=|:\d+)') $false;Assert-Equal ($html-match'打印页|源码页') $false;Assert-Equal ($html-match'src/app\.ts') $false
    Assert-Throws {Write-StandardSourceHtml -Plan $long -SoftwareName '软件' -Version '1.0.0' -OutputPath $htmlPath|Out-Null} 'Refusing to overwrite source material'

    $unicodeRoot=Join-Path $root 'unicode';$unicodeRelative='源码 目录/源 文件😀.ts';$unicodePath=Join-Path $unicodeRoot $unicodeRelative.Replace('/','\');New-Item -ItemType Directory -Path (Split-Path -Parent $unicodePath) -Force|Out-Null;$unicodeLine=('a'*54)+'😀'+"`t"+'尾';[IO.File]::WriteAllText($unicodePath,$unicodeLine,[Text.UTF8Encoding]::new($false));$unicodeEntry=[pscustomobject]@{path=$unicodeRelative;lines=1;bytes=(Get-Item $unicodePath).Length;sha256=Get-LowerHash $unicodePath};$unicodeCanonical='{0}|{1}|{2}|{3}'-f$unicodeEntry.path,$unicodeEntry.lines,$unicodeEntry.bytes,$unicodeEntry.sha256;$unicodeDigest=[BitConverter]::ToString(([Security.Cryptography.SHA256]::Create().ComputeHash([Text.UTF8Encoding]::new($false).GetBytes($unicodeCanonical)))).Replace('-','').ToLowerInvariant();$unicodeManifest=[pscustomobject]@{manifestVersion='1.0';templateId='project_task_management';totalFiles=1;totalLines=1;sha256=$unicodeDigest;files=@($unicodeEntry)};$unicodePlan=Get-StandardSourcePrintPlan -RepositoryRoot $unicodeRoot -SourceManifest $unicodeManifest;$unicodeSegments=@($unicodePlan.pages.lines|Where-Object{[string]$_.path-eq$unicodeRelative}|Sort-Object continuation|ForEach-Object{[string]$_.text});Assert-Equal ($unicodeSegments-join'') $unicodeLine;Assert-Equal $unicodeSegments.Count 2;$unicodeHtmlPath=Join-Path $root 'unicode-source.html';$unicodeHtml=Write-StandardSourceHtml -Plan $unicodePlan -SoftwareName 'Unicode 软件' -Version '1.0.0' -OutputPath $unicodeHtmlPath;Assert-Equal ($unicodeHtml-match[regex]::Escape($unicodeRelative)) $false;Assert-Match $unicodeHtml '尾'

    $junctionRoot=Join-Path $root 'junction-root';$outsideRoot=Join-Path $root 'junction-outside';New-Item -ItemType Directory -Path $junctionRoot,$outsideRoot -Force|Out-Null;$outsideFile=Join-Path $outsideRoot 'file.ts';[IO.File]::WriteAllText($outsideFile,'export const outside = true;',[Text.UTF8Encoding]::new($false));New-Item -ItemType Junction -Path (Join-Path $junctionRoot 'linked') -Target $outsideRoot|Out-Null;$junctionEntry=[pscustomobject]@{path='linked/file.ts';lines=1;bytes=(Get-Item $outsideFile).Length;sha256=Get-LowerHash $outsideFile};$junctionCanonical='{0}|{1}|{2}|{3}'-f$junctionEntry.path,$junctionEntry.lines,$junctionEntry.bytes,$junctionEntry.sha256;$junctionDigest=[BitConverter]::ToString(([Security.Cryptography.SHA256]::Create().ComputeHash([Text.UTF8Encoding]::new($false).GetBytes($junctionCanonical)))).Replace('-','').ToLowerInvariant();$junctionManifest=[pscustomobject]@{manifestVersion='1.0';templateId='project_task_management';totalFiles=1;totalLines=1;sha256=$junctionDigest;files=@($junctionEntry)};Assert-Throws {Get-StandardSourcePrintPlan -RepositoryRoot $junctionRoot -SourceManifest $junctionManifest|Out-Null} 'reparse point'

    $planPath=Join-Path $root 'source-plan.json';[IO.File]::WriteAllText($planPath,($long|ConvertTo-Json -Depth 10),[Text.UTF8Encoding]::new($false));$sourceHtmlSha256=Get-LowerHash $htmlPath
    $worker=Join-Path $PSScriptRoot '..\template\tools\word-export-worker.ps1';$repoRoot=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path;$materialsTool=Join-Path $PSScriptRoot '..\template\tools\build-materials.ps1';. $materialsTool -ProjectRoot $repoRoot -NoBuild
    [void](Get-ExplicitSourcePlan -PlanPath $planPath -HtmlPath $htmlPath -ExpectedPages 60 -ManifestSha256 $long.sourceManifestSha256 -SelectionSha256 $long.selectionSha256 -HtmlSha256 $sourceHtmlSha256 -ExpectedTotalFiles $long.totalFiles -ExpectedLogicalLines $long.totalLogicalLines -ExpectedPrintLines $long.totalPrintLines)
    $tamperedPlan=$long|ConvertTo-Json -Depth 10|ConvertFrom-Json;$tamperedPlan.pages[0].lines[0].text='tampered';$tamperedPlanPath=Join-Path $root 'tampered-plan.json';[IO.File]::WriteAllText($tamperedPlanPath,($tamperedPlan|ConvertTo-Json -Depth 10),[Text.UTF8Encoding]::new($false));Assert-Throws {Get-ExplicitSourcePlan -PlanPath $tamperedPlanPath -HtmlPath $htmlPath -ExpectedPages 60 -ManifestSha256 $long.sourceManifestSha256 -SelectionSha256 $long.selectionSha256 -HtmlSha256 $sourceHtmlSha256 -ExpectedTotalFiles $long.totalFiles -ExpectedLogicalLines $long.totalLogicalLines -ExpectedPrintLines $long.totalPrintLines|Out-Null} 'selection digest is invalid'
    $metadataPlan=$long|ConvertTo-Json -Depth 10|ConvertFrom-Json;$metadataPlan.firstRange='2-31';$metadataPlanPath=Join-Path $root 'metadata-plan.json';[IO.File]::WriteAllText($metadataPlanPath,($metadataPlan|ConvertTo-Json -Depth 10),[Text.UTF8Encoding]::new($false));Assert-Throws {Get-ExplicitSourcePlan -PlanPath $metadataPlanPath -HtmlPath $htmlPath -ExpectedPages 60 -ManifestSha256 $long.sourceManifestSha256 -SelectionSha256 $long.selectionSha256 -HtmlSha256 $sourceHtmlSha256 -ExpectedTotalFiles $long.totalFiles -ExpectedLogicalLines $long.totalLogicalLines -ExpectedPrintLines $long.totalPrintLines|Out-Null} 'derived metadata is invalid'
    $tamperedHtmlPath=Join-Path $root 'tampered-source.html';[IO.File]::WriteAllText($tamperedHtmlPath,($html+'tampered'),[Text.UTF8Encoding]::new($false));Assert-Throws {Get-ExplicitSourcePlan -PlanPath $planPath -HtmlPath $tamperedHtmlPath -ExpectedPages 60 -ManifestSha256 $long.sourceManifestSha256 -SelectionSha256 $long.selectionSha256 -HtmlSha256 $sourceHtmlSha256 -ExpectedTotalFiles $long.totalFiles -ExpectedLogicalLines $long.totalLogicalLines -ExpectedPrintLines $long.totalPrintLines|Out-Null} 'HTML does not match'
    $work=[pscustomobject]@{HtmlPath=$htmlPath;SourcePlanPath=$planPath;SourceHtmlSha256=$sourceHtmlSha256;DocxPath=(Join-Path $root 'source.docx');PdfPath=(Join-Path $root 'source.pdf');SourceDocument=$true;ExplicitSourceDocument=$true;ExpectedSourcePages=60;SourceManifestSha256=[string]$long.sourceManifestSha256;SelectionSha256=[string]$long.selectionSha256;SourceTotalFiles=[int]$long.totalFiles;SourceTotalLogicalLines=[int]$long.totalLogicalLines;SourceTotalPrintLines=[int]$long.totalPrintLines;PrototypeDocument=$false;ApplicationDocument=$false;SoftwareName='边缘云智能业务分发平台软件';Version='1.0.0'}
    $workPath=Join-Path $root 'source.work.json';[IO.File]::WriteAllText($workPath,($work|ConvertTo-Json -Depth 5),[Text.UTF8Encoding]::new($false))
    $previousErrorAction=$ErrorActionPreference;try{$ErrorActionPreference='Continue';$workerOutput=& powershell -NoProfile -ExecutionPolicy Bypass -File $worker -ProjectRoot $repoRoot -WorkItemsPath $workPath 2>&1|Out-String}finally{$ErrorActionPreference=$previousErrorAction};if($LASTEXITCODE-ne0){throw "Source Word export failed: $workerOutput"}
    $word=$null;$document=$null;try{$word=New-Object -ComObject Word.Application;$word.Visible=$false;$word.DisplayAlerts=0;$document=$word.Documents.Open($work.DocxPath,$false,$true);$document.Repaginate();Assert-Equal ([int]$document.ComputeStatistics(2)) 60;$documentText=[string]$document.Content.Text;Assert-Match $documentText 'export const line00001 = 1;';Assert-Match $documentText 'export const line05000 = 5000;';Assert-Equal ($documentText-match'F\d{3}(?:\s*=|:\d+)') $false;Assert-Equal ($documentText-match'打印页|源码页|src/app\.ts') $false}finally{if($null-ne$document){try{$document.Close($false)}catch{};try{[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($document)}catch{}};if($null-ne$word){try{$word.Quit()}catch{};try{[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($word)}catch{}}}
    Assert-Equal (Get-MaterialsPdfPageCount $work.PdfPath) 60;Assert-Equal (Get-DocxVariable $work.DocxPath 'SourceManifestSha256') ([string]$long.sourceManifestSha256);Assert-Equal (Get-DocxVariable $work.DocxPath 'SourceSelectionSha256') ([string]$long.selectionSha256)

    $multiRoot=Join-Path $root 'multi';$multiEntries=[Collections.Generic.List[object]]::new();for($fileIndex=1;$fileIndex-le20;$fileIndex++){$relative='很长,的中文源码目录名称/业务模块分组目录/第'+$fileIndex.ToString('D2')+'个业务处理文件名称.ts';$path=Join-Path $multiRoot $relative.Replace('/','\');New-Item -ItemType Directory -Path (Split-Path -Parent $path) -Force|Out-Null;$content="export const first$fileIndex = true;`nexport const second$fileIndex = true;";[IO.File]::WriteAllText($path,$content,[Text.UTF8Encoding]::new($false));$multiEntries.Add([pscustomobject]@{path=$relative;lines=2;bytes=(Get-Item $path).Length;sha256=Get-LowerHash $path})};$multiCanonical=(@($multiEntries|Sort-Object path)|ForEach-Object{'{0}|{1}|{2}|{3}'-f$_.path,$_.lines,$_.bytes,$_.sha256})-join"`n";$multiDigest=[BitConverter]::ToString(([Security.Cryptography.SHA256]::Create().ComputeHash([Text.UTF8Encoding]::new($false).GetBytes($multiCanonical)))).Replace('-','').ToLowerInvariant();$multiManifest=[pscustomobject]@{manifestVersion='1.0';templateId='project_task_management';totalFiles=20;totalLines=40;sha256=$multiDigest;files=$multiEntries.ToArray()};$multiPlan=Get-StandardSourcePrintPlan -RepositoryRoot $multiRoot -SourceManifest $multiManifest;Assert-Equal $multiPlan.expectedPageCount 1;Assert-Equal @($multiPlan.pages[0].lines).Count 40;Assert-Equal (@($multiPlan.pages[0].mappings).Count-gt0) $true;$multiHtmlPath=Join-Path $root 'multi-source.html';$multiHtml=Write-StandardSourceHtml -Plan $multiPlan -SoftwareName '多文件测试软件' -Version '1.0.0' -OutputPath $multiHtmlPath;$multiVisible=[Net.WebUtility]::HtmlDecode([regex]::Replace($multiHtml,'<[^>]+>',''));Assert-Equal ($multiVisible-match'F\d{3}(?:\s*=|:\d+)') $false;foreach($entry in $multiEntries){Assert-Equal ($multiVisible-match[regex]::Escape([IO.Path]::GetFileName([string]$entry.path))) $false};Assert-Match $multiVisible 'export const first1 = true;';Assert-Match $multiVisible 'export const second20 = true;';$multiPlanPath=Join-Path $root 'multi-plan.json';[IO.File]::WriteAllText($multiPlanPath,($multiPlan|ConvertTo-Json -Depth 10),[Text.UTF8Encoding]::new($false));$collisionPlan=$multiPlan|ConvertTo-Json -Depth 10|ConvertFrom-Json;$firstSelected=[string]$collisionPlan.selectedFiles[0];$comma=$firstSelected.IndexOf(',');$collisionPlan.selectedFiles=@($firstSelected.Substring(0,$comma),$firstSelected.Substring($comma+1))+@($collisionPlan.selectedFiles|Select-Object -Skip 1);$collisionPath=Join-Path $root 'collision-plan.json';[IO.File]::WriteAllText($collisionPath,($collisionPlan|ConvertTo-Json -Depth 10),[Text.UTF8Encoding]::new($false));Assert-Throws {Get-ExplicitSourcePlan -PlanPath $collisionPath -HtmlPath $multiHtmlPath -ExpectedPages $multiPlan.expectedPageCount -ManifestSha256 $multiPlan.sourceManifestSha256 -SelectionSha256 $multiPlan.selectionSha256 -HtmlSha256 (Get-LowerHash $multiHtmlPath) -ExpectedTotalFiles $multiPlan.totalFiles -ExpectedLogicalLines $multiPlan.totalLogicalLines -ExpectedPrintLines $multiPlan.totalPrintLines|Out-Null} 'selection digest is invalid';$multiWork=[pscustomobject]@{HtmlPath=$multiHtmlPath;SourcePlanPath=$multiPlanPath;SourceHtmlSha256=Get-LowerHash $multiHtmlPath;DocxPath=(Join-Path $root 'multi-source.docx');PdfPath=(Join-Path $root 'multi-source.pdf');SourceDocument=$true;ExplicitSourceDocument=$true;ExpectedSourcePages=[int]$multiPlan.expectedPageCount;SourceManifestSha256=[string]$multiPlan.sourceManifestSha256;SelectionSha256=[string]$multiPlan.selectionSha256;SourceTotalFiles=[int]$multiPlan.totalFiles;SourceTotalLogicalLines=[int]$multiPlan.totalLogicalLines;SourceTotalPrintLines=[int]$multiPlan.totalPrintLines;PrototypeDocument=$false;ApplicationDocument=$false;SoftwareName='多文件测试软件';Version='1.0.0'};$multiWorkPath=Join-Path $root 'multi.work.json';[IO.File]::WriteAllText($multiWorkPath,($multiWork|ConvertTo-Json -Depth 5),[Text.UTF8Encoding]::new($false));$previousErrorAction=$ErrorActionPreference;try{$ErrorActionPreference='Continue';$multiWorkerOutput=& powershell -NoProfile -ExecutionPolicy Bypass -File $worker -ProjectRoot $repoRoot -WorkItemsPath $multiWorkPath 2>&1|Out-String}finally{$ErrorActionPreference=$previousErrorAction};if($LASTEXITCODE-ne0){throw "Multi-file source Word export failed: $multiWorkerOutput"};Assert-Equal (Get-MaterialsPdfPageCount $multiWork.PdfPath) ([int]$multiPlan.expectedPageCount);$word=$null;$document=$null;try{$word=New-Object -ComObject Word.Application;$word.Visible=$false;$word.DisplayAlerts=0;$document=$word.Documents.Open($multiWork.DocxPath,$false,$true);$document.Repaginate();Assert-Equal ([int]$document.ComputeStatistics(2)) ([int]$multiPlan.expectedPageCount);$multiDocumentText=[string]$document.Content.Text;Assert-Match $multiDocumentText 'export const first1 = true;';Assert-Match $multiDocumentText 'export const second20 = true;';Assert-Equal ($multiDocumentText-match'F\d{3}(?:\s*=|:\d+)') $false;foreach($entry in $multiEntries){Assert-Equal ($multiDocumentText-match[regex]::Escape([IO.Path]::GetFileName([string]$entry.path))) $false}}finally{if($null-ne$document){try{$document.Close($false)}catch{}};if($null-ne$word){try{$word.Quit()}catch{}}}

    [IO.File]::AppendAllText((Join-Path $longRoot 'src\app.ts'),'tampered',[Text.UTF8Encoding]::new($false))
    Assert-Throws {Get-StandardSourcePrintPlan -RepositoryRoot $longRoot -SourceManifest $longManifest|Out-Null} 'Source manifest file changed'
}
finally{if(Test-Path -LiteralPath $root){Remove-Item -LiteralPath $root -Recurse -Force}}
